(()=>{const report=()=>parent.postMessage({kind:'qa-metrics',width:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,dialog:document.querySelector('dialog[open]')?.getBoundingClientRect().width||null,brokenImages:Array.from(document.images).filter(i=>i.complete&&i.naturalWidth===0&&i.getClientRects().length>0).length},location.origin);window.addEventListener('resize',report);window.addEventListener('load',report);document.addEventListener('click',()=>setTimeout(report,400));setInterval(report,1200);report();})();
